import type {EditorialEntry,ContentSection} from '@/types';
const reviewed='2026-11-10';
const tourism='https://www.tourism.rajasthan.gov.in/jaisalmer.html';
const section=(heading:string,body:string):ContentSection=>({heading,body});
const links={desert:[{path:'/experiences/desert-safari',title:'Compare Jaisalmer desert safaris'},{path:'/experiences/overnight-desert',title:'Plan a desert camping night'},{path:'/travel-guide/sam-versus-khuri',title:'Choose between Sam and Khuri'}],city:[{path:'/itineraries/2-day-jaisalmer',title:'Put this stop in a two-day itinerary'},{path:'/places/patwon-ki-haveli',title:'Explore Patwon Ki Haveli'},{path:'/places/gadisar-lake',title:'Plan a Gadisar Lake visit'}]};
/** Original planning advice; source links establish destination context, not live prices or operator promises. */
const improvements:Record<string,Partial<EditorialEntry>>={
 'places/jaisalmer-fort':{sections:[section('Why visit Jaisalmer Fort?','Jaisalmer Fort is a living neighbourhood as well as a heritage attraction. Plan for public lanes, architecture and everyday life rather than treating the entire fort as one ticketed museum. Choose one or two interior visits that interest you, then leave time to explore without blocking residents or shop entrances.'),section('A practical half-day plan','Start with the fort while your group is comfortable walking. Break for water and shade, then decide whether a palace or temple visit suits your time and mobility. Our planning allowance of two to three hours is a suggested visit length, not an opening schedule. Pair the fort with one haveli rather than booking an immediate desert pickup after several interior visits.'),section('Tickets, access and respectful visiting','Check the current ticket and photography rules at each attraction inside the fort; one admission should not be assumed to cover every interior. Uneven stone, gradients and stairs may affect access. Ask your guide about the exact route before paying, and ask residents before taking their portrait.'),section('Connecting the city and desert','Keep your hotel checkout, luggage storage and dune transfer separate from sightseeing. A city-and-desert package must say which vehicle, guide and admissions are included. If your arrival is late, make the fort the following morning’s main visit and shorten a secondary stop instead of rushing through the neighbourhood.')],related:links.city},
 'places/patwon-ki-haveli':{sections:[section('What makes Patwon Ki Haveli different?','Patwon Ki Haveli is a heritage stop for travellers interested in carved sandstone, merchant architecture and the detail of domestic spaces. Look at the façade from the lane before deciding which interior to enter. Rajasthan Tourism highlights the narrow-street setting and surviving interior decoration; an interior ticket is a separate decision from simply viewing the exterior.'),section('How to fit it into a city route','Visit after the fort with a meal or rest break between them. Our suggested sixty to ninety minutes is a planning allowance that you can shorten for an exterior visit or extend for a guided interior. Decide how much walking your group wants before adding several more havelis to the same morning.'),section('Check your ticket and walking access','Ask which building or museum section the quoted admission covers, whether a camera charge applies and which rooms are open. Narrow lanes and internal stairs can matter more than the distance on a map. Arrange a sensible drop-off point and avoid relying on a car reaching the doorway.'),section('What the package should specify','A route mentioning Patwon Ki Haveli does not by itself include an entry ticket or private guide. Compare admission, guiding, waiting time and the return pickup separately. If you mainly want architecture photographs, explain that preference before agreeing to a longer museum-led visit.')],related:links.city},
 'places/gadisar-lake':{sections:[section('Why include Gadisar Lake?','Gadisar, also written Gadsisar, is Jaisalmer’s historic water-conservation lake. Its sandstone edges and pavilions make it a different kind of stop from the fort’s narrow lanes. Visit for a quieter walk and an outdoor view, with boating treated as a separate optional activity rather than an assumed inclusion.'),section('A relaxed visit around your itinerary','Place the lake at the end of a city day or on a free morning before departure. Leave room for sitting and observing instead of using it as a hurried photograph stop between transfers. If your train or flight is early, enjoy the lake the previous day rather than relying on a last-minute visit.'),section('Boats, weather and access','Confirm operating conditions, the boarding point, life jackets, the charge basis and the current return time directly with the boat operator. Boating may not suit every visitor or weather condition. Check the walking surface and access to the waterside for your own mobility requirements; an attractive lake photograph does not establish step-free boarding.'),section('Combine it with the right city stops','Pair a lake walk with a fort or haveli visit, leaving a comfortable meal break. A desert night normally needs its own transfer plan, so do not add an uncertain boat departure immediately before a camp’s reporting deadline. Ask whether your chosen package includes the city vehicle or only the desert leg.')],source:'https://www.incredibleindia.gov.in/en/rajasthan/jaisalmer',related:links.city},
 'places/sam-sand-dunes':{sections:[section('What to choose at Sam Sand Dunes','Treat a dune outing, a camel ride, a jeep activity, a cultural evening and an overnight camp as different services. They can be combined, but the name Sam Sand Dunes does not include all of them. Choose whether your main purpose is outdoor time, a programme with dinner or an overnight stay before comparing prices.'),section('Day visit or overnight camp?','A day outing can suit travellers who prefer a city hotel and a return transfer. A camp night changes your luggage, bathroom, meal and next-morning arrangements. Ask for the exact camp location and tent type, not just a photograph of dunes. Verify whether a sunset outing ends at your camp or requires another pickup.'),section('What to ask a safari operator','For a camel activity, distinguish the ride duration from transport and waiting time. For a jeep, confirm vehicle occupancy, route, restraint arrangements and whether the price is per vehicle or per person. Ask about lower-impact alternatives if riding does not suit your group; a vehicle activity is not automatically appropriate for children or everyone with back or neck concerns.'),section('Build a realistic city-to-desert day','Keep an arrival buffer, a lunch break and a clear pickup point in the city. Do not add every roadside attraction before a fixed evening reporting time. Save the operator contact and confirm the city return point before departure. Current conditions and supplier confirmation take priority over a suggested itinerary.')],related:links.desert},
 'places/khuri':{sections:[section('Planning a Khuri desert experience','Khuri offers another base for exploring the desert around Jaisalmer. Choose the actual host, route and overnight arrangement instead of assuming the destination name guarantees privacy or a quieter programme. A village stay, tented camp and open-sky night have different facilities and should be compared separately.'),section('Sam or Khuri for your trip?','Decide what matters most: a particular camp, a shorter outing, a cultural programme, bathroom comfort or time away from a scheduled group. Compare dated supplier quotes for both areas. Neither a lower headline price nor a general destination description proves that one location is better for every visitor.'),section('Before agreeing to an overnight','Confirm bedding, the bathroom’s location, drinking water, meal times, mobile connectivity expectations and the arrangements if weather changes. Ask what happens if you decide not to ride a camel. For a family or private group, establish the tent or room occupancy and the return vehicle rather than assuming exclusivity from the word private.'),section('Give the desert its own space','Leave the city with a clear meeting time, water and a confirmed return plan. If visiting the village, respect occupied homes and ask before photographs. A Khuri stay can be the desert chapter of a three-day trip; it should not be compressed between a late arrival and an early onward connection.')],related:links.desert},
 'places/kuldhara':{sections:[section('Kuldhara as a heritage visit','Visit Kuldhara for its village remains and the questions they raise about settlement and desert life. Rajasthan Tourism identifies it as a heritage destination. Stories about haunting are folklore, not a verified promise of paranormal activity. Focus your visit on the setting, surviving structures and information available on site.'),section('Add it only when the route works','Discuss Kuldhara as an optional excursion when planning a city-to-desert day. Confirm the actual detour, vehicle waiting time and current access before adding it to a sunset programme. If a camp has a firm reporting time, shorten another stop or choose a different day rather than assuming every attraction lies on the direct route.'),section('Prepare for an outdoor stop','Carry water, sun protection and footwear for uneven ground. Ask about shade, toilets and walking access if those facilities affect your group. Stay on permitted paths and do not climb or move fragile masonry for photographs. Our suggested visit length is an editorial allowance; verify current entry conditions locally.'),section('Separate admission from the package','Ask whether the quote includes this stop, any current admission and the vehicle time. A package itinerary may mention Kuldhara as a possible visit without pricing every cost. Keep enough flexibility to omit it if heat, access or a delayed departure makes the day uncomfortable.')],related:links.desert},
 'places/bada-bagh':{sections:[section('A distinct heritage landscape','Bada Bagh is known for its sandstone cenotaphs near Jaisalmer. Treat it as a separate heritage stop rather than another museum inside the fort. It suits travellers who want to spend time looking at the architecture and landscape without trying to collect every city attraction in one circuit.'),section('Planning the visit and return','Discuss the route and pickup point with your driver before leaving town. Choose a visit window that leaves time to return comfortably, especially if a train, flight or camp programme follows. Our timing suggestions are editorial, and current entry arrangements and photography conditions must be checked at the site.'),section('Access and respectful photography','Expect outdoor walking and check the surfaces for your group’s mobility. Carry water and respect any closed areas or conservation barriers. Do not climb structures to reproduce a photograph. A guide, camera permission and admission need to be identified separately in a supplier quote.')],related:links.city},
 'travel-guide/best-time-to-visit':{sections:[section('Choose a season around your activities','The cooler part of the year is generally more comfortable for outdoor sightseeing and desert excursions in Rajasthan. October to March is a useful starting window, not a guarantee of mild conditions every day. Choose your dates around walking comfort, accommodation and the activities you actually want, then check the local forecast shortly before departure.'),section('Cool-season days and desert nights','Build a day with heritage walking, a rest break and a separate desert outing. Pack layers for evenings instead of assuming daytime sunshine means a warm overnight tent. Ask whether your accommodation supplies appropriate bedding and whether your dinner or programme is outdoors. Festivals and holidays can change demand; confirm the actual event date rather than relying on an old calendar.'),section('Hotter months: shorten the outdoor plan','Make fewer commitments to long outdoor walks. Discuss shade, water, rest breaks and cooling in the actual hotel or tent before reserving. An air-conditioned city room does not establish cooling at a desert camp. Moving a difficult activity to another day is often more useful than trying to keep an overloaded itinerary.'),section('Rain, wind and changing access','Check current weather and road conditions with the operator before an excursion. Ask how an unsafe safari, interrupted programme or unusable overnight setup is handled, and get alternatives and refund terms in writing. A desert location does not mean the weather can never disrupt a trip.'),section('Match the trip length to the arrival','Two full local days can cover a city day and a desert experience; three or four allow more rest and flexibility. Count the journey to Jaisalmer separately. Before paying the ₹99 token, review the selected date, proposed inclusions and conditions for supplier confirmation.')],source:'https://www.tourism.rajasthan.gov.in/best-time-to-visit.html',related:[{path:'/itineraries/3-day-jaisalmer',title:'Plan three usable local days'},{path:'/travel-guide/packing-and-accessibility',title:'Packing and access planning'}]},
 'travel-guide/sam-versus-khuri':{sections:[section('Compare a plan, not just a location name','Sam and Khuri are both starting points for desert experiences near Jaisalmer. The useful comparison is between specific dated arrangements: your pickup, activity, host, meal plan, sleeping setup and return. No destination name alone guarantees a private dune, an uncrowded evening or a particular level of accommodation.'),section('If you want an evening without changing hotels','Compare a round-trip outing from your city accommodation. Ask when you leave, how much of the quoted duration is travel, what happens between activities and when you return. If you want only dune time, do not pay for a bundled camp dinner or programme without deciding whether it suits you.'),section('If the overnight is the main experience','Compare tent or room type, attached versus shared bathrooms, electricity, bedding, meal arrangements and the next morning’s departure. Ask for the property name and actual room photographs. Destination photography illustrates a place; it cannot confirm your accommodation.'),section('Choose around your group','Families may prioritise a bathroom near the sleeping space and an easy return. Couples may prioritise private occupancy and fewer scheduled activities. A solo traveller may value a confirmed shared departure, but sharing must be offered rather than assumed. Ask about alternatives to riding and about the conditions for changing plans.'),section('Compare the complete quote','Put Sam and Khuri quotes on the same basis: the same travellers, night count, transfers, meals, activities, taxes and exclusions. The ₹99 token is deducted from the selected local package total. Final services and availability remain subject to supplier confirmation.')],related:links.desert},
 'travel-guide/how-to-reach':{sections:[section('Choose your arrival before your local package','Start by checking a complete dated journey to Jaisalmer and the return journey. Rajasthan Tourism describes air, rail and road access, but a destination page is not a live timetable. Book origin transport separately unless a written quote explicitly includes it. A ₹99 local reservation token is not a flight, train or intercity-bus ticket.'),section('Arriving by air','Search your origin to Jaisalmer as one itinerary and compare all stops, baggage and elapsed time. Seasonal announcements do not guarantee service on your dates. If you consider another Rajasthan airport, add the onward journey, any overnight stay and the risk of separate tickets before deciding it saves money or time.'),section('Arriving by train','Check the exact origin station, operating day and arrival day in the railway enquiry service. A night spent on a train is not a hotel or camp night. If the arrival is too late for an evening activity, choose a city stay first rather than relying on a rushed transfer to the dunes.'),section('Arriving by road','For a bus, verify the actual boarding and drop-off points. For a private car, request tolls, parking, driver allowance, rest stops and one-way or return charges in the same quote. Do not compare a local per-person sightseeing estimate with an intercity per-vehicle price.'),section('Local pickups and desert transfers','Give the operator the exact station, airport or hotel and the arrival time on the ticket. Establish whether a transfer ends in Jaisalmer city or at a named camp. Confirm waiting charges, luggage arrangements, the return point and what happens if the first journey is delayed. Local sightseeing, a dune activity and a camp transfer can be separate services.')],related:[{path:'/jaisalmer-travel-from',title:'Choose an origin-city travel guide'},{path:'/travel-guide/local-transport',title:'Compare local transport options'}]},
};
Object.assign(improvements,{
 'experiences/overnight-desert':{sections:[section('Choose a sleeping arrangement, not just a camp label','A Jaisalmer desert camping night can mean a tented property, a basic camp setup or an open-sky arrangement. Compare what you will sleep in, how many people share it and the actual bathroom and bedding. A destination photograph does not show your contracted room. Ask for the property name and current accommodation photographs before treating the arrangement as confirmed.'),section('Work out the whole overnight timeline','Agree when you leave the city, the reporting time, which activities happen before dinner and when you return the next morning. Confirm luggage storage if you check out of a city hotel first. A one-night camp product does not necessarily provide a city room before or after it, even when the wider trip lasts two calendar days.'),section('Check meals, water and activities individually','Ask whether dinner and breakfast are included, what drinking water is supplied and how dietary requests are handled. Camel rides, jeep activities and folk programmes are separate inclusion checks. A proposed itinerary can mention an optional activity without adding its cost to the estimate.'),section('Facilities matter after dark','Check the bathroom location, lighting, electricity, bedding and the weather alternative. Confirm the distance between your sleeping space and the shared facilities if travelling with children or anyone who needs assistance. Do not assume a premium allowance guarantees a pool, air conditioning or a named luxury property.'),section('Payment and supplier confirmation','Compare the same group size, occupancy, transfers, meals, activities, taxes and exclusions. Review the selected departure and refund conditions before reserving. The ₹99 token counts toward the package total; the travel desk still needs to confirm arrangements and the final supplier price.')],related:links.desert},
 'itineraries/2-day-jaisalmer':{sections:[section('Who this two-day plan suits','Use this route when you have two usable local days and can reach Jaisalmer before the first planned visit. It combines city heritage with one desert night; it is an editorial suggestion rather than a guaranteed timetable. If your journey takes most of the first day or you depart early on the second, choose fewer stops or add another night.'),section('Day 1 morning: fort and one city stop','Start with the living fort lanes and select one interior visit rather than every museum. Follow with either a haveli or a relaxed city lunch, depending on arrival and walking comfort. Keep luggage with an agreed host or hotel. Entry tickets, guiding and storage must be checked separately from a sightseeing route.'),section('Day 1 afternoon and evening: one desert plan','Leave enough time for the agreed transfer and camp reporting time. Choose either Sam or Khuri and review the actual tent, bathroom, meal and activity inclusions. Do not add a jeep activity, camel ride and every roadside stop unless the supplier has confirmed a realistic programme. Riding is optional only where the chosen arrangement allows an alternative.'),section('Day 2: return, then a flexible city visit','Confirm breakfast and the return pickup before the overnight. If your departure leaves room, use a gentle lake walk or one short heritage stop. If it does not, prioritise the station, airport or onward vehicle. The drive from camp, a meal and luggage collection all take time; a planned morning return is not a guaranteed connection.'),section('What to reserve and what to budget','This route has one overnight on the first day. If you need a room on the second night, compare a two-night package instead. Read the package inclusion statuses and full group estimate. Keep origin travel, admissions, excluded meals and optional activities outside the ₹99 token; that token is deducted from the selected local package total.')],related:[{path:'/packages/2-nights-3-days-jaisalmer',title:'Need two nights? Compare three-day packages'},{path:'/experiences/overnight-desert',title:'Check the overnight camping arrangements'}]},
 'itineraries/3-day-jaisalmer':{sections:[section('Three days, two nights and a usable arrival','This suggested three-day Jaisalmer itinerary uses a city night followed by a desert night. It gives heritage and the dunes their own space. Count the journey to Jaisalmer separately, and change the order if the arrival or return ticket leaves less local time. The route is a planning suggestion; actual hotel, camp and activity arrangements require confirmation.'),section('Day 1: settle into the Golden City','Drop luggage at your agreed city accommodation, then choose fort lanes and one interior or haveli visit. Keep a rest and meal break rather than filling the arrival day with every attraction. A gentle lake visit can finish the day if your group has energy. Confirm the city room night and any early check-in or luggage arrangement.'),section('Day 2: choose your desert chapter','Use the morning for a city stop you deliberately left out, then take the confirmed transfer to Sam or Khuri. Choose the activity that suits your group and review whether a ride, jeep, dinner or performance is included, optional or unspecified. Check the actual tent occupancy and bathroom. A stop such as Kuldhara belongs in the route only if the detour and reporting time work.'),section('Day 3: return without rushing the departure','After the agreed breakfast and camp pickup, allow time for a meal, luggage collection and the onward journey. A craft stop or lake walk can fill spare time; it should be the first thing you drop when transport changes. Ask for the exact drop-off point and keep the operator contact accessible.'),section('Compare the night split before booking','A two-night package might use a different city/desert split from this itinerary. Compare the actual stay route, group size, vehicle basis and meal statuses in the package details. Three days does not include a separate Tanot and Longewala excursion automatically. Choose a longer trip if that district day is important, and review the ₹99 reservation conditions before paying.')],related:[{path:'/packages/2-nights-3-days-jaisalmer',title:'Compare packages for two nights and three days'},{path:'/itineraries/4-day-jaisalmer',title:'Allow another day for a district excursion'}]},
 'itineraries/4-day-jaisalmer':{sections:[section('Who benefits from four local days?','Four usable days suit travellers who want a city visit, a desert night and time for one considered extra excursion or a slower pace. They do not mean every distant attraction can be combined in one outing. Keep arrival and departure travel separate from local days and confirm the actual three-night accommodation split in your quote.'),section('Day 1: a measured city introduction','Begin with the fort and one haveli, with time for lunch and rest. Avoid turning a long travel day into a full walking circuit. Settle into the city property and agree the next day’s pickup, vehicle and meal plan. Airport or railway transfers are not implied by a city stay.'),section('Day 2: choose one extra focus','Discuss a Tanot and Longewala excursion, an authorised nature visit or another city-focused day according to your interests. Obtain current access and identification requirements directly from the responsible authority or supplier. This itinerary does not promise entry to restricted border posts. Keep enough time for the return rather than adding a desert evening at the end of a long district drive.'),section('Day 3: move to the desert deliberately','Transfer to the named camp or overnight host at the agreed time. Review the activity, dinner, water, bathroom and bedding arrangements individually. Keep the option of simply enjoying the outdoor setting if riding does not suit you. Do not assume three nights means three desert nights or a particular property category.'),section('Day 4: breakfast, return and a flexible finish','Agree the return pickup before the overnight and allow a comfortable departure buffer. Add a lake or craft stop only if time remains after luggage and meals. Swap the district and desert days if confirmed access or weather calls for it, then check whether any changed services affect the price.'),section('Budget for what is actually selected','Ask for the nights, day vehicles, longer-excursion mileage, admissions, guide, meals and optional activities in one itemised group quote. The ₹99 token goes toward the selected local package; it does not pay for all four days. Supplier confirmation and the accepted cancellation terms still apply.')],related:[{path:'/places/tanot-mata-temple',title:'Plan a Tanot visit carefully'},{path:'/packages',title:'Compare actual package night splits'}]},
});

const additionalNotes:Record<string,Partial<EditorialEntry>>={"places/nathmal-ki-haveli":{sections:[section("Choose this stop for the fa\u00e7ade and details","Make Nathmal Ki Haveli a deliberate architectural stop on a city walking route. Compare it with a longer museum visit at another haveli rather than assuming every haveli offers the same interior experience. Leave time to look from the public street without obstructing businesses or residents. A guide should explain what you can actually enter that day."),section("Plan the approach and the next stop","Agree where a vehicle can drop your group and how much walking remains. Ask about occupied or closed areas, photography permission and any admission before entering. If walking or stairs are difficult, describe that requirement to the operator before choosing the route. Keep a rest break between this stop and a longer fort visit; a route mention does not include transport or guiding automatically.")]},"places/salim-singh-ki-haveli":{sections:[section("Give the building its own visit","Choose Salim Singh Ki Haveli when its architecture interests you, rather than adding it only to complete a list of havelis. Ask what parts are currently accessible and what the ticket covers. A short exterior stop and a guided interior visit need different amounts of time, and neither should displace a confirmed departure or camp meeting."),section("Check walking access and costs","Allow for the approach through the city and check the actual stairs or uneven surfaces with your host. Confirm admission, camera rules and guide charges separately. If comparing a city package, check whether this particular haveli is in the included route or remains an optional stop. Destination photographs are reference views, not confirmation of current visitor access.")]},"places/tanot-mata-temple":{sections:[section("Give the district excursion a separate day","Plan Tanot as a longer excursion from Jaisalmer rather than an extra stop between city sightseeing and a camp dinner. Ask for the full route, vehicle, meal or rest stops and the return plan. If combining it with Longewala, agree that route in advance and leave flexibility for access or road changes."),section("Verify the exact permitted itinerary","Temple access and restricted border-post access are different matters. This guide does not promise a permit or entry to forward posts. Confirm current requirements with the responsible authority and operator, and carry only the identification they actually request. Obtain any additional mileage, waiting and cancellation terms in the written quote. A Tanot route in a package does not establish every optional visit or admission.")]},"places/longewala":{sections:[section("Plan a focused district outing","Treat Longewala as a considered district visit with its own transport and return time. Discuss whether Tanot belongs in the same confirmed route or whether a different focus suits your interests. Do not schedule a full city circuit and an evening desert programme on either side of a long excursion without a workable operator plan."),section("Access and quote checks","Verify the current visitor arrangements, opening conditions and any identification requirements directly before travel. Restricted border-post access is not included by this guide. Ask what the vehicle quote includes, where you stop for meals and water, and which admissions or guide services remain separate. Keep a flexible return period instead of using an approximate excursion finish as a guaranteed flight connection.")]},"places/desert-national-park":{sections:[section("Nature viewing is different from a dune activity","Discuss a lawful nature-focused visit with an authorised guide or operator. A general jeep safari or dune-bashing product is not proof of access to a protected area. Establish the permitted route and the arrangements for your date before comparing it with a recreational desert activity. Wildlife sightings depend on conditions and are never guaranteed."),section("Prepare the group and the day","Ask about current access, vehicle requirements, walking, shade, water and the right equipment for the proposed activity. Keep noise and disturbance low and follow guide instructions and conservation rules. Price any necessary permits, guide and transport explicitly. If wildlife is the main reason for your trip, leave time for the conditions rather than fitting a nature visit into a brief stop before camp.")]},"places/amar-sagar":{sections:[section("Choose a quieter heritage stop","Use Amar Sagar as a separate lake-and-heritage visit rather than confusing it with Gadisar Lake in the city itinerary. Decide which setting interests you and ask for a route that leaves time to look around. A photograph of water does not establish current water levels, boating or access to every nearby building."),section("Check the approach and onward route","Confirm the actual drop-off, walking surfaces, access to individual sites and any current admission or photography restrictions. Ask before entering religious or occupied areas and follow local instructions. If the visit sits on a city-to-desert day, compare the detour with the camp reporting time. Agree whether vehicle waiting and a guide are included rather than treating all nearby heritage stops as one ticket.")]},"experiences/heritage-walk":{sections:[section("Agree a route that fits your pace","A heritage walk can focus on public fort lanes, haveli fa\u00e7ades, shops or selected interiors. Ask where it starts and finishes, how much walking and stair climbing it involves, whether there are rest stops and which languages the guide can actually offer. A walking route does not automatically include museum or temple admission."),section("Choose what is included before the walk","Compare guiding time, group size, ticket costs and the return meeting point. Ask before photographing residents and do not enter private spaces for a picture. If you have a vehicle meeting afterward, agree a reachable pickup point rather than expecting it at the end of a narrow lane. Retain a flexible meal break before a separate dune excursion.")]},"experiences/desert-evening":{sections:[section("Match the evening to your main interest","Decide whether you want dune time, a particular activity, dinner or a cultural programme. An evening package can combine services, but each needs its own inclusion and timing check. Compare the actual reporting point and the time spent outdoors rather than assuming every sunset photograph represents the same experience."),section("Plan a return before you leave","If you keep a city hotel, agree who brings you back and where the pickup is after the programme. Check whether dinner, water, a ride and any vehicle activity are included or optional. Leave room for the weather and changing sunset time. An evening outing is not an overnight booking; add a named stay only when you want and have confirmed it.")]},"experiences/lake-photography":{sections:[section("Work around the scene, not a guaranteed photograph","Choose time to observe the lake, water, architecture and changing light without promising a particular reflection, bird sighting or weather condition. Keep camera equipment and your group clear of walking routes. If you photograph people, ask first and respect a refusal."),section("Separate a photo walk from a boat activity","A waterside walk, boat hire and a photography guide are different services. Confirm which is included and whether camera or location restrictions apply. Check boarding conditions, life jackets and the return time if boating is part of the plan. Keep a weather alternative and a departure buffer rather than scheduling a boat immediately before an onward connection.")]},"experiences/food-and-craft":{sections:[section("Choose an experience with transparent stops","Discuss whether the route is a market walk, a meal, a craft demonstration or shopping time. Ask which tastings or purchases are included and whether the guide receives a commission at suggested shops. You should be able to enjoy looking without assuming a purchase is required."),section("Dietary and purchase questions matter","Explain ingredients or preparation you need to avoid and ask the actual food provider to confirm; a destination or cuisine label does not settle dietary suitability. For a craft purchase, compare the materials, price and delivery terms directly with the seller and keep a receipt. A trip estimate does not include shopping purchases or shipping unless explicitly written into the quote.")]},"experiences/folk-culture":{sections:[section("Compare the programme itself","A cultural evening can include music, dance, dinner or another scheduled activity, but none should be inferred from the venue name. Ask who is performing, which elements are proposed, the seating arrangement and the current reporting and finish times. A general destination description does not guarantee a particular artist or private performance."),section("Make the evening comfortable","Confirm whether seating is outdoors, how food and drinking water are arranged, and whether toilets and the return pickup suit your group. Ask before filming performers and agree payment for a specially requested performance separately. Respect the artists\u2019 work rather than treating a programme as background for an unlimited photo session. Keep overnight accommodation separate unless the selected package includes it.")]},"itineraries/1-day-jaisalmer":{sections:[section("Decide whether this is a city day or a desert day","A single usable day is best planned around one main focus. Choose city heritage with a fort, one haveli and a flexible lake visit, or choose a confirmed desert outing with the necessary transfers. Trying to add every city attraction before a fixed sunset activity leaves little room for arrival delays, rest or meals."),section("Make departure timing the deciding factor","Check where luggage is stored, when the vehicle returns and how long you need before the actual train, flight or onward ride. Admission, guiding, meals and activities remain individual inclusion checks. This itinerary does not contain an overnight stay; compare a one-night package separately if your arrival or departure needs accommodation.")]},"travel-guide/desert-camp-checklist":{sections:[section("Ask for the property and sleeping setup","Request the named property, room or tent category, current photographs, occupancy, bedding and bathroom arrangement. Destination photography is not a room photograph. Clarify electricity, cooling or heating where relevant, and how far shared facilities are from the sleeping space. A stay-type request does not automatically price an unavailable property."),section("Write down the complete overnight programme","Record the meeting point, transfer, reporting time, actual activity duration, dinner, drinking water, breakfast and return pickup. Ask which activities are proposed, included or optional, and how dietary needs are handled. Give the operator your arrival ticket details so an uncertain connection is not treated as a guaranteed camp check-in."),section("Agree changes before paying","Ask what happens if weather makes an activity unsafe or the intended room cannot be supplied. Review alternatives, cancellations, the refund method and whom you contact for help. Compare the full group total and unpriced requests before paying the \u20b999 token. The token is part of the package total, while final supplier services still need confirmation.")]},"travel-guide/camel-or-jeep":{sections:[section("Compare the experience and the charging basis","A camel experience can be priced by rider or activity, while a jeep quote may be for a whole vehicle. Use the same group count and ask for the actual riding or driving time, excluding transfers and waiting. A cheaper per-person headline is not comparable with an exclusive vehicle total."),section("Suitability needs an individual conversation","Ask how you board, whether assistance and restraints are available, what the route feels like and what you can do if you prefer not to participate. A jeep is not automatically a medically suitable alternative to a camel. Explain practical access needs before payment and seek individual advice where health or pregnancy affects the decision."),section("Choose one focus before adding a bundle","You can decide that outdoor time without riding is the right option. If you choose both activities, confirm their order, the transfer between them and whether dinner or a camp night follows. Read each selected inclusion status rather than relying on a route description. Ask about weather changes and cancellation before reserving.")]},"travel-guide/responsible-thar-travel":{sections:[section("Respect people and permitted places","Ask before photographing residents, children, shops or performers. Keep home entrances and walking routes clear and avoid entering occupied spaces without permission. Follow the instructions at religious sites and protected landscapes. A route suggested on a website is not permission to enter a closed area or a restricted border post."),section("Choose operators through practical questions","Ask how animals are handled, what waste arrangements are in place, who guides the visit and what happens when an activity is unsafe. Avoid promises of guaranteed wildlife encounters or driving anywhere on the dunes. Pay agreed fees fairly, keep rubbish with you until proper disposal and discuss a lower-impact alternative if a proposed activity is not comfortable.")]},"travel-guide/packing-and-accessibility":{sections:[section("Plan clothing around the actual overnight","Bring sun protection and layers appropriate to the forecast rather than assuming a sunny desert day means a warm tent at night. Ask what bedding and water the accommodation supplies before adding them to your luggage. Keep your operator contact, arrival details and a charged phone accessible instead of leaving everything in stored luggage."),section("Describe access needs with specific questions","Ask about the surface and distance of each walk, stairs, vehicle entry height, toilet location and assistance available at the named property. A private vehicle or premium room label does not establish step-free access. A camel ride, jeep drive and boat boarding require separate suitability checks. Keep an alternative visit or rest period in the plan rather than committing everyone to the same activity.")]}};

const experience=(slug:string,title:string,description:string,image:string,sections:ContentSection[],related=links.desert):EditorialEntry=>({slug,title,description,image,sections,related,eyebrow:'Jaisalmer desert experiences',location:'Jaisalmer & the Thar Desert',duration:'Choose a dated itinerary',source:tourism,updated:reviewed});
const additions:Record<string,EditorialEntry[]>={
 experiences:[
 experience('desert-safari','Jaisalmer Desert Safari: Compare Your Options','Compare camel rides, jeep safaris and desert evenings in Jaisalmer. Understand the route, price basis, transfers, safety questions and overnight options.','khuri',[
 section('What does a desert safari actually include?','A Jaisalmer desert safari can mean a camel activity, a jeep excursion or a wider day that also includes transfers and an evening programme. These are different purchases. Begin with the experience you want and ask for each included service to be written down, rather than comparing two offers that only share the word safari.'),section('Camel, jeep or time on the dunes without riding?','A camel experience and a jeep activity feel different and have different group arrangements. Ask about the actual ride or drive duration, waiting time, the route and the option to sit out. Watching the landscape without riding can be a deliberate choice. Explain access needs before agreeing to an activity; no general destination guide can establish suitability for every traveller.'),section('Day outing, dinner programme or camp night','A city-hotel base can work with an agreed return transfer after the excursion. A dinner programme adds its own reporting and finishing times. An overnight changes your bedding, bathroom and luggage requirements. Keep these decisions separate so that a low ride price is not mistaken for a complete evening or a hotel-and-camp package.'),section('Sam and Khuri: compare actual arrangements','Rajasthan Tourism describes camel activities at both Sam and Khuri, and jeep activities around desert tracks in the wider area. This does not establish a specific supplier, exclusive route or live availability. Compare the host, vehicle, pickup and facilities for your date. Ask how weather or access changes affect your selected plan.'),section('Read the quote before reserving','Check whether the charge is per person, per tent or per vehicle. Record the number of travellers, the capacity model, entry costs, water, meals, transfers and optional extras. JaisalGo shows the group estimate and the ₹99 reservation token separately; that token counts toward the total. Supplier confirmation is still required, and a route mention is not proof that every activity is included.')]),
 experience('camel-safari','Jaisalmer Camel Safari: Route & Booking Guide','Plan a camel safari near Jaisalmer, Sam or Khuri. Check riding duration, transfers, optional camp stays, group suitability and the actual package inclusions.','khuri',[
 section('Choose the length of the riding experience','Ask how long you will actually be on the camel and whether the quoted duration also includes the drive, briefing or a sunset wait. A short activity is different from a longer route or an overnight desert plan. Decide which you want before choosing the cheapest advertised label.'),section('Agree pickup, meeting and return points','If you are staying in Jaisalmer city, establish whether the price includes reaching the dune meeting point. Ask where the activity ends and who arranges the return. If a camp stay follows, confirm whether the camel ride is included in that camp’s package or remains a separate optional cost.'),section('Suitability and animal welfare questions','Ask the operator about mounting, assistance, the terrain and alternatives if a traveller cannot ride. Discuss a child’s participation individually instead of assuming the adult booking covers them. Observe the animals and decline handling you are uncomfortable with. A guide cannot guarantee that a particular activity is suitable for pregnancy, pain or a medical condition; seek individual advice when needed.'),section('Sunset and overnight plans','Sunset timing is seasonal and a photograph does not promise a private dune. Leave flexibility for the weather and the operator’s meeting time. For an overnight, confirm the sleeping setup, bathroom, water and weather alternative separately from the camel activity.'),section('What to compare before paying','Use the same riding duration and transfer basis when comparing quotes. Check the guide or handler arrangement, exclusions and cancellation terms. Browse the actual package inclusion statuses; a camel mentioned in an itinerary can still be optional. Reserve with ₹99 only after reviewing the selected package and supplier-confirmation conditions.')]),
 experience('jeep-safari','Jaisalmer Jeep Safari: Vehicles, Costs & Planning','Compare Jaisalmer jeep safari options by vehicle capacity, route and actual inclusions. Plan transfers, group costs and questions to ask before reserving.','sam',[
 section('Start with the vehicle and route','Jeep safari can refer to different desert routes and driving styles. Ask where the activity takes place, how long the drive lasts and whether reaching the activity is part of that duration. Do not assume a city pickup, a wildlife visit or an exclusive vehicle from the name alone.'),section('Per vehicle is different from per person','Request the vehicle capacity and the total for your entire group. If your group needs more than one vehicle, compare the combined amount. A seat-share estimate is meaningful only where shared seats are actually offered. JaisalGo identifies vehicle-based products and shows a full group estimate so you can check the charging basis.'),section('Discuss safety before booking','Ask about the driver, the route conditions, seat and restraint arrangements, passenger limits and the option of a gentler drive. Discuss children and access requirements directly. A jeep is not automatically an accessible substitute for every traveller who prefers not to ride a camel.'),section('Keep the evening plan separate','A jeep activity does not itself include a camel ride, dinner, folk programme or camp night. Confirm each item and the transfers between them. If you return to a city hotel, agree a finishing time and drop-off point instead of assuming the camp will arrange a vehicle afterward.'),section('Weather, changes and payment','Ask which alternative or refund applies if the route cannot operate. Check the selected date, the group quote and supplier-confirmation conditions before paying the ₹99 token. Optional add-ons remain extra unless the selected package explicitly includes them; a route photograph is not evidence of live availability.')]),
 ],
 'travel-guide':[
 experience('local-transport','Getting Around Jaisalmer: Local Transport Guide','Plan Jaisalmer sightseeing and desert transfers with clear pickup points, walking routes, vehicle quotes, luggage plans and accessible-travel questions.','lanes',[
 section('Use walking where the route suits you','Heritage lanes and some attraction approaches are better understood as walking visits than door-to-door car stops. Ask for the exact drop-off and meeting points and the amount of walking between them. A short map distance can still involve stairs, uneven stone or a busy lane. Plan rest and water around your group’s needs.'),section('Compare a point-to-point ride with a day vehicle','For one transfer, agree the destination and what waiting is included. For a sightseeing vehicle, ask about the route, hours, included stops, parking, driver allowance and charges if you change the programme. Neither arrangement automatically includes attraction tickets or a guide.'),section('The desert transfer is its own decision','Confirm the named camp or dune meeting point and the city return point. A drop in town is different from a transfer to Sam or Khuri. If a safari and dinner use different hosts, establish who handles the journey between them and who is responsible if the first activity runs late.'),section('Arrivals, luggage and access','Give the actual station, airport or hotel address, not just Jaisalmer as a city name. Agree luggage storage when hotel checkout and the next departure do not line up. If you need a particular vehicle entry height, child arrangement or luggage space, confirm the specific vehicle rather than relying on a private-transfer label.'),section('Compare the complete price','Ask for per-vehicle versus per-person charges, passenger capacity, tolls or parking where applicable, waiting, late pickup and cancellation. A transfer allowance in a provisional package is a cost model until the supplier confirms the arrangement. Keep written details and the operator contact with your itinerary.')],links.city),
 experience('international-visitors','Jaisalmer India Travel Guide for International Visitors','Plan a Jaisalmer visit in India with arrival connections, visa-source checks, INR budgeting, desert-stay questions and realistic Rajasthan itinerary advice.','fort-day',[
 section('Place Jaisalmer within your India itinerary','Count the journey into and out of Jaisalmer separately from days spent sightseeing. If you combine Rajasthan cities, choose each transfer before reserving a tight camp arrival or onward departure. A two-day local package is not a two-day international arrival-to-departure itinerary.'),section('Use official visa and entry information','Check the Government of India visa portal and your own government’s travel advice for your nationality, passport and travel purpose. Eligibility and permitted entry points can change. This guide does not determine visa eligibility, arrange immigration clearance or imply that Jaisalmer is your international entry airport.'),section('Connections, baggage and arrival timing','Compare the complete booked journey, including the exact airport or station, baggage conditions and any separate tickets. Seasonal air routes are not year-round guarantees. Keep time for delays before committing to a sunset activity. Give your host the arrival details from the ticket and confirm where the pickup ends.'),section('Understand prices in Indian rupees','JaisalGo’s displayed package estimates use INR. Compare the full group amount, night count, accommodation, transfers, meals, activities and exclusions. The ₹99 token is credited toward the local package total; it is not the price of a complete trip. Your card issuer may apply its own conversion or international-payment charges, and gateway acceptance should be checked through the actual checkout.'),section('Choose accommodation and activities deliberately','Ask for a named property, room or tent photographs, bathroom arrangements, bedding and drinking water. Confirm dietary requirements rather than assuming a general meal inclusion answers them. Walking access, mounting a camel and entering a jeep require separate suitability checks. A private booking does not guarantee an isolated desert location.'),section('Travel respectfully and keep a useful record','Ask before photographing residents, respect occupied homes and follow local entrance rules. Save your operator contacts, quote, accepted cancellation terms and private ticket link. Keep the private booking link within your travel party; use the public verification QR to check status without exposing contact details.')],[{path:'/travel-guide/how-to-reach',title:'Plan your Jaisalmer arrival'},{path:'/itineraries/4-day-jaisalmer',title:'A slower four-day local itinerary'},{path:'/travel-guide/budget-planning',title:'Build an INR travel budget'}]),
 ],
};
export function enrichEditorial(collection:string,items:EditorialEntry[]):EditorialEntry[]{return [...items.map(item=>{const key=`${collection}/${item.slug}`,patch=improvements[key],notes=additionalNotes[key];return patch?{...item,...patch,updated:reviewed}:notes?{...item,sections:[...item.sections,...notes.sections!],updated:reviewed}:item}),...(additions[collection]||[]).map(item=>collection==='travel-guide'?{...item,eyebrow:'Practical travel planning',duration:'Planning guide',...(item.slug==='international-visitors'?{sources:[{title:'Government of India: official visa portal',url:'https://indianvisaonline.gov.in/evisa/'},{title:'Rajasthan Tourism: destination information',url:tourism}]}:{})}:item)];}
